{"teaching_intent":"让学生通过操控初速度、抛射角、高度、重力与质量，观察平抛/斜抛过程中同一时刻的位置、速度方向、加速度方向以及动能/势能/机械能的同步变化；验证水平速度不变、竖直方向受重力加速的因果，理解最高点、落地时刻、射程与机械能守恒等关键事件如何随初始条件改变。","html":"<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>平抛与斜抛运动</title>
<style>
*{box-sizing:border-box}
body{font-family:system-ui,-apple-system,"Microsoft YaHei",sans-serif;margin:0;background:#f5f7fa;color:#1f2937}
#app{max-width:1100px;margin:0 auto;padding:16px}
header{text-align:center;margin-bottom:12px}
h1{margin:0;font-size:1.35rem}
.cards{display:grid;grid-template-columns:1fr;gap:12px}
@media(min-width:800px){.cards{grid-template-columns:1.4fr 1fr}}
.card{background:#fff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,.08);padding:12px}
#stage{width:100%;height:auto;background:#eef2f7;border-radius:8px;touch-action:none}
.controls{display:grid;gap:10px}
.control{display:flex;flex-direction:column;gap:4px}
.control label{font-size:.85rem;display:flex;justify-content:space-between}
.control input[type=range]{width:100%;height:44px}
.readouts{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;font-size:.85rem;margin-top:10px}
.readout{background:#f3f4f6;padding:8px;border-radius:6px}
.readout b{display:block;font-size:.95rem}
.playbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:10px}
.playbar button{min-height:44px;min-width:44px;border:0;border-radius:8px;background:#2563eb;color:#fff;font-size:.9rem;cursor:pointer}
.playbar button.secondary{background:#64748b}
.playbar input[type=range]{flex:1;min-width:120px;height:44px}
.energy{margin-top:10px}
.barwrap{display:flex;align-items:center;gap:6px;margin:4px 0;font-size:.8rem}
.bar{height:18px;border-radius:4px;transition:width .08s linear}
.ke{background:#f59e0b}
.pe{background:#10b981}
.me{background:#6366f1}
.status{margin-top:8px;font-size:.9rem;color:#374151}
</style>
</head>
<body>
<!--HARNESS_PRIMITIVES-->
<!--HARNESS_MODEL-->
<!--HARNESS_INPUT-->
<div id="app">
<header>
<h1>平抛与斜抛运动</h1>
<p>拖动参数，观察轨迹、速度/加速度方向与能量的因果变化</p>
</header>
<div class="cards">
<div class="card">
<svg id="stage" viewBox="0 0 800 400" preserveAspectRatio="xMidYMid meet">
<defs>
<marker id="ar" markerWidth="10" markerHeight="10" refX="9" refY="3" orient="auto" markerUnits="strokeWidth">
<path d="M0,0 L0,6 L9,3 z" fill="#ef4444"/>
</marker>
<marker id="ar2" markerWidth="10" markerHeight="10" refX="9" refY="3" orient="auto" markerUnits="strokeWidth">
<path d="M0,0 L0,6 L9,3 z" fill="#8b5cf6"/>
</marker>
</defs>
<line id="ground" x1="40" y1="360" x2="760" y2="360" stroke="#94a3b8" stroke-width="2"/>
<text x="40" y="380" font-size="12" fill="#64748b">地面 y=0</text>
<polyline id="traj" fill="none" stroke="#3b82f6" stroke-width="2" stroke-dasharray="4,3"/>
<line id="vel" stroke="#ef4444" stroke-width="2" marker-end="url(#ar)"/>
<line id="acc" stroke="#8b5cf6" stroke-width="2" marker-end="url(#ar2)"/>
<circle id="ball" r="8" fill="#1d4ed8" stroke="#fff" stroke-width="2"/>
<text id="posL" x="0" y="0" font-size="12" fill="#1e293b"></text>
<text id="velL" x="0" y="0" font-size="12" fill="#ef4444"></text>
<text id="accL" x="0" y="0" font-size="12" fill="#8b5cf6"></text>
</svg>
<div class="status" data-readout>准备就绪</div>
</div>
<div class="card">
<div class="controls" id="controls"></div>
<div class="readouts">
<div class="readout">物理时间 t/s<b data-physical-time>0.00</b></div>
<div class="readout">演示倍率<b data-demo-time>×1.0</b></div>
<div class="readout">飞行时间/s<b id="flt">--</b></div>
<div class="readout">射程/m<b id="rng">--</b></div>
<div class="readout">最大高度/m<b id="hmax">--</b></div>
<div class="readout">最高点时刻/s<b id="tapex">--</b></div>
<div class="readout">等高地最佳角/°<b id="opt">--</b></div>
<div class="readout">速度大小/m/s<b id="vnow">--</b></div>
<div class="readout">速度方向/°<b id="anow">--</b></div>
</div>
<div class="playbar">
<button id="playBtn">播放</button>
<button id="slowBtn" class="secondary">慢放</button>
<button data-replay id="replayBtn" class="secondary">重放</button>
<input type="range" id="scrub" min="0" max="1" step="0.001" value="0">
</div>
<div class="energy">
<div class="barwrap"><span style="width:3.5em">动能</span><div id="keBar" class="bar ke" style="width:0"></div><b id="keVal">0 J</b></div>
<div class="barwrap"><span style="width:3.5em">势能</span><div id="peBar" class="bar pe" style="width:0"></div><b id="peVal">0 J</b></div>
<div class="barwrap"><span style="width:3.5em">机械能</span><div id="meBar" class="bar me" style="width:0"></div><b id="meVal">0 J</b></div>
</div>
</div>
</div>
</div>
<script>
(function(){
'use strict';
const defaults={angle_deg:0.0,g_m_s2:10.0,mass_kg:1.0,mode:"horizontal",speed_m_s:10.0,x0_m:0.0,y0_m:20.0};
const hi=globalThis.__HARNESS_INPUT__;
const scenario=Object.assign({},(hi&&hi.scenario)||defaults);
const model=globalThis.coursewareModel;
const prim=globalThis.CoursewarePrimitives;
const $=id=>document.getElementById(id);
const controls=$('controls');
const traj=$('traj'),ball=$('ball'),vel=$('vel'),acc=$('acc'),posL=$('posL'),velL=$('velL'),accL=$('accL');
const readout=document.querySelector('[data-readout]');
const physEl=document.querySelector('[data-physical-time]');
const demoEl=document.querySelector('[data-demo-time]');
const playBtn=$('playBtn'),slowBtn=$('slowBtn'),replayBtn=$('replayBtn'),scrub=$('scrub');
const VW=800,VH=400,PAD=40;
const vScale=2.2,aScale=1.6;
const defs=[
{k:'speed_m_s',id:'speed',min:0,max:30,step:0.5,label:'初速度 v₀',unit:'m/s'},
{k:'angle_deg',id:'angle',min:-90,max:90,step:1,label:'抛射角 θ',unit:'°'},
{k:'y0_m',id:'y0',min:0,max:50,step:1,label:'初始高度 h',unit:'m'},
{k:'g_m_s2',id:'g',min:1,max:20,step:0.5,label:'重力加速度 g',unit:'m/s²'},
{k:'mass_kg',id:'m',min:0.1,max:5,step:0.1,label:'质量 m',unit:'kg'}
];
let states=[],events={},flightTime=0,scaleX=1,scaleY=1,energyMax=1;
let tl=null,speed=1,playing=false,tPhys=0,dragging=false;
let rafId=null,startT=0,startPhys=0;
function fmt(n,f=2){return(n==null||isNaN(n))?'--':n.toFixed(f)}
function setA(el,a,v){el.setAttribute(a,v)}
function lerp(a,b,u){return a+(b-a)*u}
function buildControls(){
controls.innerHTML='';
defs.forEach(d=>{
 const div=document.createElement('div');div.className='control';
 const lab=document.createElement('label');
 const val=document.createElement('span');val.id=d.id+'Val';
 lab.innerHTML='<span>'+d.label+'</span>';lab.appendChild(val);
 const input=document.createElement('input');
 input.type='range';input.min=d.min;input.max=d.max;input.step=d.step;
 input.value=scenario[d.k];input.dataset.key=d.k;input.setAttribute('data-control','');
 input.addEventListener('input',()=>{scenario[d.k]=parseFloat(input.value);val.textContent=input.value+' '+d.unit});
 input.addEventListener('change',sampleAndReset);
 div.appendChild(lab);div.appendChild(input);controls.appendChild(div);
 val.textContent=input.value+' '+d.unit;
});
}
function axis(){const a=[],n=600,m=60;for(let i=0;i<=n;i++)a.push(i*m/n);return a}
function sampleAndReset(){
scenario.mode=Math.abs(scenario.angle_deg)<0.1?'horizontal':'oblique';
const res=model.sample({scenario:scenario,times_s:axis()});
states=res.states||[];events=res.events||{};
flightTime=events.flight_time_s||0;
if(states.length<2){renderZero();updateEventReadouts();return}
setScales();energyMax=Math.max(1e-6,states.reduce((m,s)=>Math.max(m,s.mechanical_j||0),0));
buildTrajectory();tPhys=0;scrub.value=0;updateEventReadouts();makeTimeline();render();
}
function setScales(){
const mx=Math.max(1,(events.range_m||0)*1.15,scenario.x0_m*1.2);scaleX=(VW-PAD*2)/mx;
const my=Math.max(1,(events.max_height_m||scenario.y0_m)*1.15,scenario.y0_m*1.15);scaleY=(VH-PAD*2)/my;
}
function buildTrajectory(){const pts=[];for(let s of states){if(flightTime&&s.t_s>flightTime+0.001)break;pts.push(coord(s.x_m,s.y_m))}setA(traj,'points',pts.join(' '))}
function coord(x,y){return (PAD+x*scaleX)+','+(VH-PAD-y*scaleY)}
function makeTimeline(){
if(tl){if(tl.pause)tl.pause();if(tl.kill)tl.kill()}
const dur=flightTime||1;
tl=prim.createTimeline({duration:dur,paused:true,onUpdate:function(){
 let t=(this&&typeof this.time==='function')?this.time():(this&&typeof this.totalTime==='function'?this.totalTime():null);
 if(typeof t==='number'&&!dragging)setPhys(t);
},onComplete:function(){pause()}});
if(tl&&typeof tl.timeScale==='function')tl.timeScale(speed);
if(tl&&typeof tl.pause==='function')tl.pause();
}
function hasTL(){return tl&&typeof tl.play==='function'&&typeof tl.pause==='function'&&typeof tl.seek==='function'&&typeof tl.timeScale==='function'}
function play(){
if(tPhys>=flightTime){tPhys=0;scrub.value=0}
playing=true;playBtn.textContent='暂停';
if(hasTL()){tl.seek(tPhys);tl.timeScale(speed);tl.play()}
else{startT=performance.now();startPhys=tPhys;rafLoop()}
}
function pause(){playing=false;playBtn.textContent='播放';if(hasTL())tl.pause();cancelAnimationFrame(rafId)}
function togglePlay(){playing?pause():play()}
function rafLoop(){
const now=performance.now();
setPhys(startPhys+(now-startT)/1000*speed);
if(tPhys>=flightTime){render();pause();return}
rafId=requestAnimationFrame(rafLoop);
}
function setPhys(t){
tPhys=Math.max(0,Math.min(t,flightTime||0));
if(!dragging)scrub.value=flightTime?tPhys/flightTime:0;
if(tl&&typeof tl.seek==='function'&&dragging)tl.seek(tPhys);
render();
}
function renderZero(){
if(!states.length){setA(ball,'cx',PAD);setA(ball,'cy',VH-PAD);return}
const s=states[0],bx=PAD+s.x_m*scaleX,by=VH-PAD-s.y_m*scaleY;
setA(ball,'cx',bx);setA(ball,'cy',by);
setA(vel,'x1',bx);setA(vel,'y1',by);setA(vel,'x2',bx);setA(vel,'y2',by);
setA(acc,'x1',bx);setA(acc,'y1',by);setA(acc,'x2',bx);setA(acc,'y2',by);
}
function render(){
if(!states.length){renderZero();return}
const t=tPhys;
let i=0;while(i+1<states.length&&states[i+1].t_s<t)i++;
const s0=states[i],s1=states[i+1]||s0;
const den=(s1.t_s-s0.t_s)||1;
const u=Math.min(1,Math.max(0,(t-s0.t_s)/den));
const x=lerp(s0.x_m,s1.x_m,u),y=Math.max(0,lerp(s0.y_m,s1.y_m,u));
const vx=lerp(s0.vx_m_s,s1.vx_m_s,u),vy=lerp(s0.vy_m_s,s1.vy_m_s,u);
const ax=lerp(s0.ax_m_s2,s1.ax_m_s2,u),ay=lerp(s0.ay_m_s2,s1.ay_m_s2,u);
const ke=lerp(s0.kinetic_j,s1.kinetic_j,u),pe=lerp(s0.potential_j,s1.potential_j,u),me=lerp(s0.mechanical_j,s1.mechanical_j,u);
const bx=PAD+x*scaleX,by=VH-PAD-y*scaleY;
setA(ball,'cx',bx);setA(ball,'cy',by);
const vl=Math.hypot(vx,vy)*vScale,va=Math.atan2(-vy,vx);
setA(vel,'x1',bx);setA(vel,'y1',by);setA(vel,'x2',bx+vl*Math.cos(va));setA(vel,'y2',by+vl*Math.sin(va));
const al=Math.hypot(ax,ay)*aScale,aa=Math.atan2(-ay,ax);
setA(acc,'x1',bx);setA(acc,'y1',by);setA(acc,'x2',bx+al*Math.cos(aa));setA(acc,'y2',by+al*Math.sin(aa));
setA(posL,'x',bx+10);setA(posL,'y',by-10);posL.textContent='x='+fmt(x)+' y='+fmt(y);
setA(velL,'x',bx+vl*Math.cos(va)+6);setA(velL,'y',by+vl*Math.sin(va));velL.textContent='v';
setA(accL,'x',bx+al*Math.cos(aa)+6);setA(accL,'y',by+al*Math.sin(aa));accL.textContent='a';
physEl.textContent=fmt(tPhys);
$('vnow').textContent=fmt(Math.hypot(vx,vy));
$('anow').textContent=fmt(Math.atan2(vy,vx)*180/Math.PI);
if(tPhys>=flightTime-0.001)readout.textContent='已落地：水平射程 '+fmt(events.range_m)+' m，飞行时间 '+fmt(flightTime)+' s';
else if((events.apex_time_s||0)>0&&Math.abs(t-events.apex_time_s)<0.05)readout.textContent='到达最高点：竖直速度为 0';
else readout.textContent='飞行中：水平速度不变，竖直方向受重力加速';
const kw=Math.min(100,ke/energyMax*100),pw=Math.min(100,pe/energyMax*100),mw=Math.min(100,me/energyMax*100);
setA($('keBar'),'style','width:'+kw+'%');setA($('peBar'),'style','width:'+pw+'%');setA($('meBar'),'style','width:'+mw+'%');
$('keVal').textContent=fmt(ke)+' J';$('peVal').textContent=fmt(pe)+' J';$('meVal').textContent=fmt(me)+' J';
}
function updateEventReadouts(){
$('flt').textContent=fmt(events.flight_time_s);$('rng').textContent=fmt(events.range_m);
$('hmax').textContent=fmt(events.max_height_m);$('tapex').textContent=fmt(events.apex_time_s);
$('opt').textContent=fmt(events.optimal_equal_height_angle_deg);
}
playBtn.addEventListener('click',togglePlay);
replayBtn.addEventListener('click',()=>{pause();setPhys(0);play()});
slowBtn.addEventListener('click',()=>{
speed=speed===1?0.25:1;slowBtn.textContent=speed===1?'慢放':'常速';demoEl.textContent='×'+speed;
if(hasTL())tl.timeScale(speed);
});
scrub.addEventListener('input',()=>{dragging=true;pause();setPhys(parseFloat(scrub.value)*(flightTime||0))});
scrub.addEventListener('change',()=>{dragging=false});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing)pause()});
buildControls();sampleAndReset();
})();
</script>
</body>
</html>"}
